// ---- the kernel ----
__global__ void __launch_bounds__(256, 1)
    layer_kernel(const __grid_constant__ static_mk::Maps maps,
                 static_mk::G g,
                 StaticTask const *static_tasks) {
  static_mk::KernelLocals L;
  static_mk::kernel_begin(g, L);
  StaticTask const *my =
      static_tasks + blockIdx.x * (static_mk::MAX_TASKS_PER_SM);
  bool warm_6 = false;  // a task of node 6 ran on this SM: its code is in the
                        // instruction cache
  bool warm_15 = false; // a task of node 15 ran on this SM: its code is in the
                        // instruction cache
  bool warm_27 = false; // a task of node 27 ran on this SM: its code is in the
                        // instruction cache
  for (int ti = 0; ti < static_mk::MAX_TASKS_PER_SM; ti++) {
    StaticTask const tk = my[ti];
    if (tk.node < 0) {
      break;
    }
    switch (tk.node) {
      case 4:
        static_mk::run_gemm_tile<StaticNode<3, 8, 1, -1, 0>,
                                 StaticParams<0, 5120, 384, 0>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<0, 2>,
                                 StaticNode<0, 0, 0>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 6:
        static_mk::run_topk_route<StaticNode<8, 1, 1, -1, 2>,
                                  StaticParams<384, 6, 1069547520, 0, 0, 0, 1>,
                                  StaticBufSlots<1>,
                                  StaticMapSlots<>,
                                  StaticNode<3, 8, 1, -1, 0, 0, 5120, 384, 0>,
                                  StaticNode<0, 0, 0>>(maps, g, L, tk, warm_6);
        warm_6 = true;
        break;
      case 9:
        static_mk::run_act_quant<StaticNode<8, 1, 1, 0, 4>,
                                 StaticParams<5120>,
                                 StaticBufSlots<3>,
                                 StaticMapSlots<>,
                                 StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 13:
        static_mk::run_gemm_fp8_tile<StaticNode<9, 4, 1, -1, 5>,
                                     StaticParams<0, 5120, 1152, 1>,
                                     StaticBufSlots<>,
                                     StaticMapSlots<3, 4, 5, 6>,
                                     StaticNode<8, 1, 1, 0, 4, 5120>,
                                     StaticNode<0, 0, 0>,
                                     StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 15:
        static_mk::run_act_quant<StaticNode<8, 1, 1, 32, 6>,
                                 StaticParams<768, 576, 1092616192>,
                                 StaticBufSlots<>,
                                 StaticMapSlots<>,
                                 StaticNode<9, 4, 1, -1, 5, 0, 5120, 1152, 1>>(
            maps, g, L, tk, warm_15);
        warm_15 = true;
        break;
      case 19:
        static_mk::run_gemm_fp8_tile<
            StaticNode<40, 1, 1, -1, 7>,
            StaticParams<0, 768, 5120, 1>,
            StaticBufSlots<>,
            StaticMapSlots<7, 8, 9, 10>,
            StaticNode<8, 1, 1, 32, 6, 768, 576, 1092616192>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 25:
        static_mk::run_swiglu_moe_experts<
            StaticNode<148, 1, 1, 64, 10>,
            StaticParams<576, 1092616192>,
            StaticBufSlots<8, 9>,
            StaticMapSlots<11,
                           12,
                           13,
                           14,
                           15,
                           16,
                           17,
                           18,
                           19,
                           5,
                           20,
                           21,
                           22,
                           23,
                           24>,
            StaticNode<8, 1, 1, 0, 4, 5120>,
            StaticNode<8, 1, 1, -1, 2, 384, 6, 1069547520, 0, 0, 0, 1>,
            StaticNode<0, 0, 0>,
            StaticNode<0, 0, 0>>(maps, g, L, tk);
        break;
      case 27:
        static_mk::run_sum_store<
            StaticNode<40, 1, 1, 192, -1>,
            StaticParams<5120, 6>,
            StaticBufSlots<11>,
            StaticMapSlots<>,
            StaticNode<40, 1, 1, -1, 7, 0, 768, 5120, 1>,
            StaticNode<148, 1, 1, 64, 10, 576, 1092616192>>(
            maps, g, L, tk, warm_27);
        warm_27 = true;
        break;
    }
  }
  static_mk::kernel_end(g, L);
}

