#define ST_CK(x)                                                               \
  do {                                                                         \
    cudaError_t e_ = (x);                                                      \
    if (e_ != cudaSuccess) {                                                   \
      fprintf(stderr,                                                          \
              "layer: %s @%d: %s\n",                                           \
              #x,                                                              \
              __LINE__,                                                        \
              cudaGetErrorString(e_));                                         \
      exit(1);                                                                 \
    }                                                                          \
  } while (0)
